#!/usr/bin/env bash
# Builds the binaries the tests run, for THIS machine (Linux): the patched Transmission, the daemon wrapper and the manager.
#   tests/build/build-test-binaries.sh   ->  .deps/test/out/{transmission_d_host,Transmission_mgr_host,transmission_i_host}
# Needs the files generated by ./build.sh (.deps/build/generated: web files and icons), clang-18, cmake,
# libssl-dev, libcurl4-openssl-dev, zlib1g-dev. Run it again after every change in src/.
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/env.sh"
[ -d "$GEN" ] || { echo "ERROR: $GEN not found: run ./build.sh first (it generates the web files and icons the tests need)" >&2; exit 1; }
export CC=clang-18 CXX=clang++-18
export CXXFLAGS="-stdlib=libc++" LDFLAGS="-stdlib=libc++"
STUBS="$BUILD_DIR/stubs"
mkdir -p "$TEST_BUILD" "$TR_BUILD" "$OUT"

# 1. Transmission for this machine: unpacked and patched tree, then libraries and the daemon objects
bash "$BUILD_DIR/prepare-test-tree.sh"
cmake -S "$TR_SRC" -B "$TR_BUILD" -G "Unix Makefiles" -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_CXX_FLAGS="-stdlib=libc++" -DCMAKE_EXE_LINKER_FLAGS="-stdlib=libc++" \
  -DENABLE_DAEMON=ON -DENABLE_GTK=OFF -DENABLE_QT=OFF -DENABLE_MAC=OFF -DRUN_CLANG_TIDY=OFF -DENABLE_UTILS=OFF -DENABLE_CLI=OFF \
  -DENABLE_TESTS=OFF -DENABLE_NLS=OFF -DINSTALL_DOC=OFF -DINSTALL_WEB=ON -DREBUILD_WEB=OFF \
  -DWITH_INOTIFY=OFF -DWITH_SYSTEMD=OFF -DENABLE_UTP=ON \
  -DUSE_SYSTEM_EVENT2=OFF -DUSE_SYSTEM_DEFLATE=OFF -DUSE_SYSTEM_DHT=OFF -DUSE_SYSTEM_MINIUPNPC=OFF \
  -DUSE_SYSTEM_NATPMP=OFF -DUSE_SYSTEM_UTP=OFF -DUSE_SYSTEM_B64=OFF -DUSE_SYSTEM_PSL=OFF > "$TEST_BUILD/cfg.log" 2>&1
( cd "$TR_BUILD"
  make -j"$(nproc)" deflate dht event miniupnpc natpmp psl MadlerCrcany libb64 libutp wildmat > "$TEST_BUILD/make1.log" 2>&1
  make -j"$(nproc)" transmission > "$TEST_BUILD/make2.log" 2>&1
  # Not the finished transmission-daemon: the daemon is linked below together with the wrapper (the ps5tm_guard_* functions live there)
  ( cd daemon && make daemon.cc.o daemon-posix.cc.o ) >> "$TEST_BUILD/make2.log" 2>&1 )

# 2. The wrapper, the manager and the icon helper (the system libraries are replaced by stubs)
cd "$OUT"
D="$TR_BUILD/daemon"
clang-18 -O2 -fPIC -c "$STUBS/hoststub.c" -o hoststub.o
clang-18 -O2 -fPIC -c "$STUBS/netwrap.c" -o netwrap.o
# the daemon
compile_c_role() { # object-dir  role-flags  sources...  (src/common/*.c is compiled once per role)
    local odir="$1" flags="$2"; shift 2
    mkdir -p "$odir"; rm -f "$odir"/*.o
    for f in "$@"; do
        clang-18 -O2 -fPIC -D_GNU_SOURCE $flags -DSHIM_VERSION="\"$VERSION\"" -Wall -Wextra -I"$SRCDIR" -I"$SRCDIR/common" -I"$GEN" -c "$f" -o "$odir/$(basename "$f" .c).o"
    done
}
compile_c_role "$OUT/obj-daemon" "-DPS5TM_DAEMON -DPS5TM_HOST_TEST" "$SRCDIR"/common/*.c "$SRCDIR"/daemon/*.c
objcopy --redefine-sym main=tr_daemon_main "$D/CMakeFiles/transmission-daemon.dir/daemon.cc.o" daemon_main.o
LINK="$(cat "$D/CMakeFiles/transmission-daemon.dir/link.txt")"
LINK="${LINK//CMakeFiles\/transmission-daemon.dir\/daemon.cc.o/$OUT/daemon_main.o}"
LINK="${LINK//-o transmission-daemon/-o $OUT/transmission_d_host $OUT/obj-daemon/*.o $OUT/hoststub.o -Wl,--wrap=pthread_create -Wl,--wrap=fork -Wl,--wrap=execvp -Wl,--wrap=open -Wl,--wrap=close -Wl,--wrap=pwrite -Wl,--wrap=pread -Wl,--wrap=ftruncate -Wl,--wrap=rename -Wl,--wrap=mkdir -Wl,--wrap=unlink -Wl,--wrap=fsync -Wl,--wrap=stat -Wl,--wrap=lstat -Wl,--wrap=statvfs}"
( cd "$D" && eval "$LINK" ) 2>&1 | tail -3
# the manager (the daemon is embedded)
compile_c_role "$OUT/obj-manager" "-DPS5TM_MANAGER" "$SRCDIR"/common/*.c "$SRCDIR"/manager/*.c
# the manager (settings server, supervisor, notifications, system service ...): src/manager/*.cc, one object each
UI_OBJS=()
for f in "$SRCDIR"/manager/*.cc; do
    o="ui_$(basename "$f" .cc).o"
    clang++-18 -stdlib=libc++ -O2 -fPIC -std=gnu++17 -Wall -Wextra -I"$SRCDIR" -DPS5TM_TEST_INHERIT_NONBLOCK -DPS5TM_SPACE_CHECK_SECONDS=5 -I"$GEN" -DPS5TM_TR_VERSION='"4.1.3"' ${UI_FLAGS:-} -c "$f" -o "$o"
    UI_OBJS+=("$o")
done
clang-18 -x assembler-with-cpp -DBLOB_PATH="\"$OUT/transmission_d_host\"" -c "$SRCDIR/asm/daemon_blob.S" -o daemon_blob.o
# the icon installation helper (on the test machine: stubs instead of libSceAppInstUtil) and its embedding
clang-18 -O2 -D_GNU_SOURCE -DPS5TM_HOST_TEST -Wall -Wextra -c "$SRCDIR/icon-helper/ps5tm_icon_helper.c" -o icon_helper.o
clang-18 -o transmission_i_host icon_helper.o -lpthread
clang-18 -x assembler-with-cpp -DICON_BLOB_PATH="\"$OUT/transmission_i_host\"" -c "$SRCDIR/asm/icon_blob.S" -o icon_blob.o
clang++-18 -stdlib=libc++ -pthread -o Transmission_mgr_host "$OUT"/obj-manager/*.o "${UI_OBJS[@]}" hoststub.o netwrap.o daemon_blob.o icon_blob.o -Wl,--wrap=pthread_create -Wl,--wrap=ps5tm_current_ip 2>&1 | tail -5
ls -l transmission_d_host Transmission_mgr_host | awk '{print $5, $9}'
